pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 0 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        vm.prank(bob);
        c.deposit{value: 0 ether}();
        // Deploy a contract that rejects ETH
        address rejector = address(new Rejector());
        vm.deal(rejector, 2 ether);
        vm.prank(rejector);
        c.deposit{value: 2 ether}();
        // Now call withdrawAll from the rejector – reference reverts, buggy silently fails
        bool ok;
        vm.prank(rejector);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, ok is false (revert); in buggy, ok is true
        assertTrue(ok, "Buggy version should allow failed ETH transfer silently");
    }
}

contract Rejector {
    receive() external payable {
        revert("I reject ETH");
    }
}

