contract Rejector {
    receive() external payable {
        revert("reject");
    }
    function callWithdrawAll(C c) public {
        c.withdrawAll();
    }
}

contract InvMutTest is Test {
    C c;
    Rejector rejector;

    function setUp() public {
        c = new C();
        rejector = new Rejector();
    }

    function testRegression_property() public {
        // Alice deposits 1 ether
        vm.deal(address(this), 1 ether);
        c.deposit{value: 1 ether}();

        // Transfer ownership of the credit to the rejector contract by having it call withdrawAll
        // First, prank as rejector; rejector calls withdrawAll
        vm.startPrank(address(rejector));
        // Before calling, we must have some ether in the rejector to pay for gas (optional)
        vm.deal(address(rejector), 1 ether);
        try rejector.callWithdrawAll(c) {
            // If no revert, the buggy version silently ignored
            fail();
        } catch {
            // Expected: reference reverts, buggy does not
        }
        vm.stopPrank();

        // Check contract balance: reference would not touch it (revert), buggy would reduce by 1 ether
        // Actually after revert, the state remains unchanged — the deposit is still there
        // In the reference, the call reverts, so withdrawAll did not execute; balance still 1 ether
        // In the buggy, withdrawAll executes but transfer fails silently; the contract's balance remains 1 ether
        // But also the credit mapping is cleared, so we need to check a different observable.
        // Let's check that the contract still has the ether: both versions end with 1 ether (bug reduced balance but revert didn't happen? Actually bug reduces balance: balance -= oCredit executes before the call, so balance = 0, but the ether is still in the contract because transfer failed; balance is a storage variable, not actual ether. So buggy balance = 0, reference balance = 1 ether.
        // We need to read balance — but it's not public. Use address(c).balance?
        // address(c).balance is actual ether, not the storage variable. The buggy contract loses 1 ether? No, the transfer failed so ether remains, but the accounting is off. Real ether balance is unchanged: 1 ether. So both have 1 ether.
        // Alternative: check a getter for credit[rejector]. Buggy set it to 0; reference set it to 0 as well (if the revert is after the state change? Actually in reference, the call to withdrawAll: it sets credit to 0 and decreases balance BEFORE the call that might revert. So even on revert, the state was already modified? But the transaction reverts everything, so state is unchanged. In bug, state is changed and stays. So after the call to withdrawAll, in reference, credit[rejector] remains 1 ether (since revert undoes), in bug it's 0.
        // So we can check c.credit(address(rejector)). That is public.
        // After the failed attempt, reference: credit still 1 ether, bug: 0.
        assertTrue(c.credit(address(rejector)) == 1 ether, "Reference should keep credit on revert");
    }
}

